import { DatabaseSync } from 'node:sqlite';
const db = new DatabaseSync(':memory:');
db.exec('CREATE TABLE despachos (id TEXT, destino TEXT, kg REAL, centavos INTEGER, estado TEXT)');

export async function crearDespacho({ destino, kg }) {
  const r = await fetch(`http://127.0.0.1:24812/cotizar?to=${destino}&kg=${kg}`);   // red adentro
  const { centavos } = await r.json();
  if (kg > 1000) throw new Error('el peso va de 0 a 1000 kg');                          // regla de negocio en el medio
  const id = 'd' + Date.now();
  db.prepare('INSERT INTO despachos VALUES (?,?,?,?,?)').run(id, destino, kg, centavos, 'pendiente'); // SQL adentro
  return { id, destino, kg, centavos, estado: 'pendiente' };
}

// Para probar la regla de los 1000 kg:
