// Núcleo de dominio: reglas del negocio, sin importar nada de afuera.
export class ReglaRota extends Error {}

export const MAX_KG = 1000;
export const ESTADOS = ['pendiente', 'en_ruta', 'entregado'];
const SIGUIENTE = { pendiente: 'en_ruta', en_ruta: 'entregado' };

export function nuevoDespacho({ id, destino, kg, centavos, ahora }) {
  if (!/^\d{4}$/.test(destino)) throw new ReglaRota('el destino es un código postal de 4 dígitos');
  if (!(kg > 0 && kg <= MAX_KG)) throw new ReglaRota(`el peso va de 0 a ${MAX_KG} kg`);
  return { id, destino, kg, centavos, estado: 'pendiente', creado: ahora };
}

export function avanzar(d) {
  const sig = SIGUIENTE[d.estado];
  if (!sig) throw new ReglaRota(`un despacho ${d.estado} no avanza`);
  return { ...d, estado: sig };
}

// Casos de uso: orquestan el dominio y hablan con el exterior solo a través de puertos.
// Puertos que esperan (los define el núcleo, los implementan los adaptadores):
//   repo:      { guardar(d), buscar(id), listar() }          (async)
//   cotizador: { cotizar({ destino, kg }) -> centavos }      (async)
//   reloj:     { ahora() -> texto ISO }
//   ids:       { nuevo() -> texto }
import { nuevoDespacho, avanzar } from './despacho.mjs';

export function crearCasosDeUso({ repo, cotizador, reloj, ids }) {
  return {
    async crearDespacho({ destino, kg }) {
      const centavos = await cotizador.cotizar({ destino, kg });
      const d = nuevoDespacho({ id: ids.nuevo(), destino, kg, centavos, ahora: reloj.ahora() });
      await repo.guardar(d);
      return d;
    },
    async avanzarDespacho(id) {
      const d = await repo.buscar(id);
      if (!d) return null;
      const nuevo = avanzar(d);
      await repo.guardar(nuevo);
      return nuevo;
    },
    listarDespachos: () => repo.listar(),
  };
}

import { DatabaseSync } from 'node:sqlite';

export function repoSqlite(archivo = ':memory:') {
  const db = new DatabaseSync(archivo);
  db.exec(`CREATE TABLE IF NOT EXISTS despachos (
    id TEXT PRIMARY KEY, destino TEXT NOT NULL, kg REAL NOT NULL,
    centavos INTEGER NOT NULL, estado TEXT NOT NULL, creado TEXT NOT NULL)`);
  const ins = db.prepare(`INSERT INTO despachos VALUES (?,?,?,?,?,?)
    ON CONFLICT(id) DO UPDATE SET destino=excluded.destino, kg=excluded.kg,
    centavos=excluded.centavos, estado=excluded.estado`);
  const uno = db.prepare('SELECT * FROM despachos WHERE id = ?');
  const todos = db.prepare('SELECT * FROM despachos ORDER BY creado, id');
  const fila = (r) => r ? { ...r } : null;
  return {
    async guardar(d) { ins.run(d.id, d.destino, d.kg, d.centavos, d.estado, d.creado); },
    async buscar(id) { return fila(uno.get(id)); },
    async listar() { return todos.all().map(fila); },
    cerrar() { db.close(); },
  };
}

export function repoMemoria() {
  const m = new Map();
  return {
    async guardar(d) { m.set(d.id, structuredClone(d)); },
    async buscar(id) { return m.has(id) ? structuredClone(m.get(id)) : null; },
    async listar() {
      return [...m.values()].sort((a, b) => a.creado.localeCompare(b.creado) || a.id.localeCompare(b.id)).map(x => structuredClone(x));
    },
  };
}

